#!/bin/sh
# Plugin databases + roles (AGENTS.md §2.6: every plugin gets its own database).
# Postgres runs this ONLY when the data directory is empty (first boot of a new environment).
# Passwords come from the server-side .env (hex, generated by stage-bootstrap.sh) — never from git.
set -eu
: "${FSP_PLUGIN_KYC_DB_PASSWORD:?}" "${FSP_PLUGIN_INVENTORY_DB_PASSWORD:?}"
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" <<SQL
CREATE ROLE fsp_plugin_kyc LOGIN PASSWORD '${FSP_PLUGIN_KYC_DB_PASSWORD}';
CREATE ROLE fsp_plugin_inventory LOGIN PASSWORD '${FSP_PLUGIN_INVENTORY_DB_PASSWORD}';
CREATE DATABASE fsp_plugin_kyc OWNER fsp_plugin_kyc;
CREATE DATABASE fsp_plugin_inventory OWNER fsp_plugin_inventory;
SQL
